import java.util.*;
public class ChatFilter {public static void main(String[] args){String[] logs={"10:05 alice Hello there","10:06 bob Good morning","bad line"};Scanner sc=new Scanner(System.in);System.out.print("Keyword: ");String key=sc.nextLine();StringBuilder report=new StringBuilder();int count=0;for(String line:logs){String[] p=line.split(" ",3);if(p.length<3)continue;if(p[2].toLowerCase().contains(key.toLowerCase())){count++;report.append(p[0]).append(" ").append(p[1]).append(": ").append(p[2]).append("\n");}}System.out.println("Matches: "+count);System.out.print(report);}}
